import React, { useState, useEffect, useRef } from 'react';
import {
  Box,
  Typography,
  Paper,
  List,
  ListItem,
  ListItemText,
  ListItemIcon,
  Chip,
  Button,
  Toolbar,
  Alert,
  CircularProgress,
  FormControlLabel,
  Switch,
  TextField,
  InputAdornment,
  Divider,
} from '@mui/material';
import PlayArrowIcon from '@mui/icons-material/PlayArrow';
import PauseIcon from '@mui/icons-material/Pause';
import ClearIcon from '@mui/icons-material/Clear';
import InfoIcon from '@mui/icons-material/Info';
import WarningIcon from '@mui/icons-material/Warning';
import ErrorIcon from '@mui/icons-material/Error';
import CheckCircleIcon from '@mui/icons-material/CheckCircle';
import SearchIcon from '@mui/icons-material/Search';

interface LogEvent {
  id: string;
  timestamp: string;
  level: 'info' | 'warning' | 'error' | 'success';
  message: string;
  source?: string;
  entry_id?: number;
  batch_id?: string;
}

const getEventIcon = (level: string) => {
  switch (level) {
    case 'error': return <ErrorIcon color="error" />;
    case 'warning': return <WarningIcon color="warning" />;
    case 'success': return <CheckCircleIcon color="success" />;
    default: return <InfoIcon color="info" />;
  }
};

const getEventColor = (level: string) => {
  switch (level) {
    case 'error': return 'error';
    case 'warning': return 'warning.main';
    case 'success': return 'success.main';
    default: return 'text.secondary';
  }
};

export default function ValidationActivityLog() {
  const [events, setEvents] = useState<LogEvent[]>([]);
  const [connected, setConnected] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [paused, setPaused] = useState(false);
  const [autoScroll, setAutoScroll] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterLevel, setFilterLevel] = useState<string>('');

  const listRef = useRef<HTMLUListElement>(null);
  const eventSourceRef = useRef<EventSource | null>(null);

  const connect = () => {
    try {
      const eventSource = new EventSource('/validation/activity-log/stream');

      eventSource.onopen = () => {
        setConnected(true);
        setError(null);
      };

      eventSource.onmessage = (event) => {
        if (!paused) {
          try {
            const newEvent: LogEvent = JSON.parse(event.data);
            newEvent.id = `${Date.now()}-${Math.random()}`;
            setEvents(prev => {
              const updated = [...prev, newEvent];
              return updated.slice(-500);
            });
          } catch (e) {
            console.error('Failed to parse event:', e);
          }
        }
      };

      eventSource.onerror = () => {
        setConnected(false);
        setError('Connection lost. Reconnecting...');
        eventSource.close();
        setTimeout(connect, 3000);
      };

      eventSourceRef.current = eventSource;
    } catch (err: any) {
      setError(err.message);
      setConnected(false);
    }
  };

  const disconnect = () => {
    if (eventSourceRef.current) {
      eventSourceRef.current.close();
      eventSourceRef.current = null;
    }
    setConnected(false);
  };

  useEffect(() => {
    connect();
    return () => disconnect();
  }, []);

  useEffect(() => {
    if (autoScroll && listRef.current) {
      listRef.current.scrollTop = listRef.current.scrollHeight;
    }
  }, [events, autoScroll]);

  const clearEvents = () => setEvents([]);

  const filteredEvents = events.filter(event => {
    const matchesSearch = searchTerm === '' || 
      event.message.toLowerCase().includes(searchTerm.toLowerCase()) ||
      (event.batch_id && event.batch_id.toLowerCase().includes(searchTerm.toLowerCase()));
    const matchesLevel = filterLevel === '' || event.level === filterLevel;
    return matchesSearch && matchesLevel;
  });

  const formatTimestamp = (timestamp: string) => {
    return new Date(timestamp).toLocaleTimeString('cs-CZ', {
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
    });
  };

  return (
    <Box>
      <Box sx={{ mb: 3 }}>
        <Typography variant="h5" fontWeight="600" gutterBottom>
          Activity Log
        </Typography>
        <Typography variant="body2" color="text.secondary">
          Real-time validation activity stream
        </Typography>
      </Box>

      <Paper sx={{ mb: 2, p: 2 }}>
        <Toolbar disableGutters sx={{ gap: 2, flexWrap: 'wrap' }}>
          <Button
            variant={connected ? "outlined" : "contained"}
            color={connected ? "error" : "success"}
            startIcon={connected ? <PauseIcon /> : <PlayArrowIcon />}
            onClick={connected ? disconnect : connect}
            size="small"
          >
            {connected ? 'Pause' : 'Resume'}
          </Button>

          <Button
            variant="outlined"
            startIcon={<ClearIcon />}
            onClick={clearEvents}
            size="small"
          >
            Clear
          </Button>

          <FormControlLabel
            control={
              <Switch
                checked={paused}
                onChange={(e) => setPaused(e.target.checked)}
                size="small"
              />
            }
            label="Pause updates"
          />

          <FormControlLabel
            control={
              <Switch
                checked={autoScroll}
                onChange={(e) => setAutoScroll(e.target.checked)}
                size="small"
              />
            }
            label="Auto-scroll"
          />

          <Box sx={{ flexGrow: 1 }} />

          <TextField
            placeholder="Search events..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            size="small"
            sx={{ width: 250 }}
            InputProps={{
              startAdornment: (
                <InputAdornment position="start">
                  <SearchIcon fontSize="small" />
                </InputAdornment>
              ),
            }}
          />

          <TextField
            select
            value={filterLevel}
            onChange={(e) => setFilterLevel(e.target.value)}
            size="small"
            sx={{ width: 150 }}
            SelectProps={{ native: true }}
          >
            <option value="">All Levels</option>
            <option value="info">Info</option>
            <option value="warning">Warning</option>
            <option value="error">Error</option>
            <option value="success">Success</option>
          </TextField>
        </Toolbar>
      </Paper>

      {error && (
        <Alert severity="warning" sx={{ mb: 2 }}>
          {error}
        </Alert>
      )}

      <Paper sx={{ height: 'calc(100vh - 400px)', minHeight: 400, display: 'flex', flexDirection: 'column' }}>
        <Box sx={{ p: 2, borderBottom: 1, borderColor: 'divider', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <Typography variant="body2" fontWeight="600">
              Live Events
            </Typography>
            <Chip
              label={connected ? 'Connected' : 'Disconnected'}
              color={connected ? 'success' : 'default'}
              size="small"
            />
            <Typography variant="body2" color="text.secondary">
              ({filteredEvents.length} events)
            </Typography>
          </Box>
        </Box>

        <List
          ref={listRef}
          sx={{ flexGrow: 1, overflow: 'auto', p: 0 }}
          disablePadding
        >
          {filteredEvents.length === 0 ? (
            <Box sx={{ p: 4, textAlign: 'center' }}>
              {connected ? (
                <CircularProgress size={24} sx={{ mb: 2 }} />
              ) : (
                <Typography variant="body2" color="text.secondary">
                  No events yet
                </Typography>
              )}
            </Box>
          ) : (
            filteredEvents.map((event) => (
              <React.Fragment key={event.id}>
                <ListItem alignItems="flex-start" sx={{ py: 1 }}>
                  <ListItemIcon sx={{ minWidth: 40 }}>
                    {getEventIcon(event.level)}
                  </ListItemIcon>
                  <ListItemText
                    primary={
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                        <Chip
                          label={event.level.toUpperCase()}
                          color={getEventColor(event.level) as any}
                          size="small"
                          sx={{ height: 20 }}
                        />
                        <Typography variant="body2" color="text.secondary">
                          {formatTimestamp(event.timestamp)}
                        </Typography>
                        {event.batch_id && (
                          <Chip
                            label={event.batch_id}
                            size="small"
                            sx={{ height: 20, fontSize: '0.7rem' }}
                          />
                        )}
                      </Box>
                    }
                    secondary={
                      <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
                        {event.message}
                      </Typography>
                    }
                  />
                </ListItem>
                <Divider />
              </React.Fragment>
            ))
          )}
        </List>
      </Paper>
    </Box>
  );
}
